#include "editor.hpp"
#include <cstdio>
namespace touch::ui {
namespace {
bool text(const char* label,std::string& value){std::vector<char> buffer(std::max(size_t(4096),value.size()+1024),0);std::copy(value.begin(),value.end(),buffer.begin());if(!ImGui::InputText(label,buffer.data(),buffer.size(),ImGuiInputTextFlags_EnterReturnsTrue))return false;value=buffer.data();return true;}
}
void Editor::inspector(){auto id=primary();auto node=document.graph.find(id);if(!node){ImGui::TextDisabled("Select an operator");return;}auto d=services.registry.find(node->type);ImGui::TextColored(ImGui::ColorConvertU32ToFloat4(theme::select),"%s",d?d->label.c_str():node->type.c_str());if(!d){ImGui::TextUnformatted("Missing plugin");return;}
if(auto it=monitor.values.find(id);it!=monitor.values.end())for(auto value:it->second)if(value){if(value->type==Signal::Video||value->type==Signal::Mask)ImGui::TextDisabled("%d x %d / %s",value->width,value->height,value->type==Signal::Mask?"mask":value->format==1?"f16":value->format==2?"u8 UNORM":"f32");if(value->type==Signal::Audio)ImGui::TextDisabled("%d ch x 480 / 48 kHz",value->components);if(value->type==Signal::Channels){ImGui::TextDisabled("%d x %d / %s",value->height,value->width,value->format==1?"f16":value->format==2?"u8 UNORM":"f32");inspected_channel=std::clamp(inspected_channel,0,value->height-1);if(ImGui::Button("<"))inspected_channel=std::max(0,inspected_channel-1);ImGui::SameLine();ImGui::SetNextItemWidth(65);int number=inspected_channel+1;if(ImGui::InputInt("##channel",&number,0))inspected_channel=std::clamp(number-1,0,value->height-1);ImGui::SameLine();if(ImGui::Button(">"))inspected_channel=std::min(value->height-1,inspected_channel+1);ImGui::SameLine();if(size_t(inspected_channel)<value->names.size())ImGui::TextUnformatted(value->names[inspected_channel].c_str());int count=std::min(8,value->width);std::string line;for(int i=0;i<count;++i){char sample[32];std::snprintf(sample,sizeof(sample),"%+.3f",value->values[inspected_channel*value->width+i*value->width/count]);if(!line.empty())line+=" ";line+=sample;if(i%3==2||i==count-1){ImGui::TextDisabled("%s",line.c_str());line.clear();}}}}
if(auto it=monitor.errors.find(id);it!=monitor.errors.end())ImGui::TextColored(ImGui::ColorConvertU32ToFloat4(theme::error),"%s",it->second.c_str());
if(d->legacy=="Image"||d->legacy=="Movie"||d->legacy=="AudioFile"||d->legacy=="Camera"){auto name=node->file.empty()?"Choose file...":std::filesystem::path(node->file).filename().string();if(ImGui::Button(name.c_str(),{ImGui::GetContentRegionAvail().x,22}))file_dialog(4);if(ImGui::IsItemHovered()&&!node->file.empty())ImGui::SetTooltip("%s",node->file.c_str());}
bool can_preview=std::any_of(d->outputs.begin(),d->outputs.end(),[](auto signal){return signal==Signal::Video||signal==Signal::Mask;});if(can_preview&&ImGui::Button(document.graph.preview==id?"Unpin preview":"Pin preview",{ImGui::GetContentRegionAvail().x,22})){document.edit([&](Graph& g){g.preview=g.preview==id?0:id;});changed();node=document.graph.find(id);}
if(d->legacy=="VideoOut"||d->legacy=="AudioOut"){auto current=d->legacy=="VideoOut"?document.graph.video:document.graph.audio;if(ImGui::Button(current==id?"Active output":"Activate output",{ImGui::GetContentRegionAvail().x,22})){document.edit([&](Graph& g){if(d->legacy=="VideoOut")g.video=id;else g.audio=id;});changed();node=document.graph.find(id);}}
for(size_t i=0;i<d->choices.size();++i){auto& choice=d->choices[i];ImGui::AlignTextToFramePadding();ImGui::TextUnformatted(choice.name.c_str());ImGui::SameLine(std::max(90.f,ImGui::GetWindowContentRegionMax().x-choice.items[node->choice(i)].size()*6-12));ImGui::PushID(int(i));if(ImGui::Button(choice.items[node->choice(i)].c_str())){document.edit([&](Graph& g){auto n=g.find(id);n->choices.resize(d->choices.size(),0);n->choices[i]=(n->choice(i)+1)%choice.items.size();});changed();node=document.graph.find(id);}ImGui::PopID();}
if(d->legacy=="SelectChannels"){auto value=node->names;if(text("Channel names",value)){document.edit([&](Graph& g){g.find(id)->names=value;});changed();node=document.graph.find(id);}}
for(size_t i=0;i<d->params.size();++i){auto& p=d->params[i];bool modulated=std::any_of(document.graph.edges.begin(),document.graph.edges.end(),[&](auto e){return e.to==Port{id,d->inputs.size()+i};});ImGui::AlignTextToFramePadding();ImGui::TextUnformatted(p.name.c_str());ImGui::SameLine(std::max(90.f,ImGui::GetWindowContentRegionMax().x-72));ImGui::PushID(int(i+100));if(modulated)ImGui::Button("Modulated",{72,22});else{ImGui::SetNextItemWidth(72);float value=node->params[i];if(ImGui::DragFloat("##value",&value,(p.max-p.min)/(ImGui::GetIO().KeyShift?1200:240),p.min,p.max,"%.2f",ImGuiSliderFlags_AlwaysClamp)){if(std::isfinite(value)){if(!parameter_before)parameter_before=document.graph;node->params[i]=value;changed();}else status="Enter a finite number";}if(ImGui::IsItemDeactivatedAfterEdit()&&parameter_before){document.commit(*parameter_before);parameter_before.reset();}}ImGui::PopID();}
if(d->legacy=="Table"){for(size_t i=0;i<node->table.size();++i){ImGui::PushID(int(i+200));std::string value=node->table[i][1];if(text(node->table[i][0].c_str(),value)){document.edit([&](Graph& g){g.find(id)->table[i][1]=value;});changed();node=document.graph.find(id);}ImGui::PopID();}}
else if(auto it=monitor.values.find(id);it!=monitor.values.end())for(auto value:it->second)if(value&&value->type==Signal::Table)for(auto row:value->rows){ImGui::TextDisabled("%s",row[0].c_str());ImGui::SameLine();ImGui::TextUnformatted(row[1].c_str());}
}
}
